// ── Pure validators (used by Wave 6 preservation tests + future CI) ─────────────────
function findDuplicates(values: string[]): string[] {
  const seen = new Set<string>()
  const dupes = new Set<string>()
  for (const v of values) {
    if (seen.has(v)) dupes.add(v)
    seen.add(v)
  }
  return Array.from(dupes)
}

export interface InventoryValidation {
  ok: boolean
  duplicateRoutes: string[]
  duplicateStorageKeys: string[]
  duplicateCloudTables: string[]
  duplicateAnalyticsEvents: string[]
  duplicateCanonicalIdKinds: string[]
  storageKeysWithMissingCloudTable: string[]   // localKey points at an unknown table
  cloudTablesNotExportCovered: string[]
  cloudTablesNotDeleteCovered: string[]
}

/** Structural integrity check over the inventory. Pure; safe to run in tests + CI. */
export function validateInventory(inv: PreservationInventory = PRESERVATION_INVENTORY): InventoryValidation {
  const tableNames = new Set(inv.cloudTables.map(t => t.table))
  const storageKeysWithMissingCloudTable = inv.storageKeys
    .filter(s => s.cloudTable !== null && !tableNames.has(s.cloudTable))
    .map(s => s.key)

  const validation: InventoryValidation = {
    ok: false,
    duplicateRoutes: findDuplicates(inv.routes.map(r => r.path)),
    duplicateStorageKeys: findDuplicates(inv.storageKeys.map(s => s.key)),
    duplicateCloudTables: findDuplicates(inv.cloudTables.map(t => t.table)),
    duplicateAnalyticsEvents: findDuplicates(inv.analyticsEvents.map(e => e.name)),
    duplicateCanonicalIdKinds: findDuplicates(inv.canonicalIds.map(c => c.kind)),
    storageKeysWithMissingCloudTable,
    cloudTablesNotExportCovered: inv.cloudTables.filter(t => !t.exportCovered).map(t => t.table),
    cloudTablesNotDeleteCovered: inv.cloudTables.filter(t => !t.deleteCovered).map(t => t.table),
  }
  validation.ok =
    validation.duplicateRoutes.length === 0 &&
    validation.duplicateStorageKeys.length === 0 &&
    validation.duplicateCloudTables.length === 0 &&
    validation.duplicateAnalyticsEvents.length === 0 &&
    validation.duplicateCanonicalIdKinds.length === 0 &&
    validation.storageKeysWithMissingCloudTable.length === 0 &&
    validation.cloudTablesNotExportCovered.length === 0 &&
    validation.cloudTablesNotDeleteCovered.length === 0
  return validation
}
